1	import { useMemo, useRef, useState, type DragEvent } from 'react';
2	import { Link } from 'react-router-dom';
3	import { CsvMapeamento } from '../components/CsvMapeamento';
4	import { CsvPrevia, type LinhaPrevia } from '../components/CsvPrevia';
5	import { Alerta, Botao, Cartao, CampoSelect, EstadoVazio, TituloPagina } from '../components/ui';
6	import {
7	  adivinharMapeamento,
8	  decodificar,
9	  desfazerImportacao,
10	  detectarSeparador,
11	  importarTransacoes,
12	  interpretarLinhas,
13	  marcarDuplicatas,
14	  parseCsv,
15	  sugerirCategoria,
16	  sugerirTags,
17	  validarArquivo,
18	} from '../domain/csv';
19	import { hojeISO } from '../domain/date';
20	import type { MapeamentoCsv } from '../domain/types';
21	import { lerArquivoBuffer } from '../lib/download';
22	import { useEstado, useStore } from '../state/store';
23	
24	interface Resumo {
25	  importacaoId: string;
26	  importadas: number;
27	  ignoradas: number;
28	  comErro: number;
29	}
30	
31	export function ImportarCsvPage() {
32	  const store = useStore();
33	  const estado = useEstado();
34	  const contasAtivas = estado.contas.filter((c) => !c.arquivada);
35	
36	  const [contaId, setContaId] = useState('');
37	  const contaEfetiva = contasAtivas.some((c) => c.id === contaId) ? contaId : (contasAtivas[0]?.id ?? '');
38	  const [nomeArquivo, setNomeArquivo] = useState<string | null>(null);
39	  const [linhasCsv, setLinhasCsv] = useState<string[][] | null>(null);
40	  const [mapeamento, setMapeamento] = useState<MapeamentoCsv | null>(null);
41	  const [selecao, setSelecao] = useState<Record<number, boolean>>({});
42	  const [categoriasEscolhidas, setCategoriasEscolhidas] = useState<Record<number, string>>({});
43	  const [erro, setErro] = useState<string | null>(null);
44	  const [resumo, setResumo] = useState<Resumo | null>(null);
45	  const [arrastando, setArrastando] = useState(false);
46	  const entrada = useRef<HTMLInputElement>(null);
47	
48	  const ultimaImportacao = estado.importacoes[estado.importacoes.length - 1];
49	
50	  const reiniciar = () => {
51	    setNomeArquivo(null);
52	    setLinhasCsv(null);
53	    setMapeamento(null);
54	    setSelecao({});
55	    setCategoriasEscolhidas({});
56	  };
57	
58	  const carregarArquivo = async (arquivo: File | undefined) => {
59	    if (!arquivo) return;
60	    setErro(null);
61	    setResumo(null);
62	    const valido = validarArquivo(arquivo.name, arquivo.size);
63	    if (!valido.ok) {
64	      reiniciar();
65	      setErro(valido.erro);
66	      return;
67	    }
68	    try {
69	      const texto = decodificar(new Uint8Array(await lerArquivoBuffer(arquivo)));
70	      const linhas = parseCsv(texto, detectarSeparador(texto));
71	      if (linhas.length === 0) {
72	        reiniciar();
73	        setErro('O arquivo está vazio.');
74	        return;
75	      }
76	      const lembrado = estado.mapeamentosCsv[contaEfetiva];
77	      const colunas = Math.max(...linhas.map((l) => l.length));
78	      const aproveitavel = lembrado && [lembrado.colData, lembrado.colDescricao, lembrado.colValor, lembrado.colCredito, lembrado.colDebito].every((c) => c === null || c < colunas);
79	      setLinhasCsv(linhas);
80	      setMapeamento(aproveitavel ? lembrado : adivinharMapeamento(linhas));
81	      setNomeArquivo(arquivo.name);
82	      setSelecao({});
83	      setCategoriasEscolhidas({});
84	    } catch (e) {
85	      reiniciar();
86	      setErro(e instanceof Error ? e.message : 'Não foi possível ler o arquivo.');
87	    }
88	  };
89	
90	  const linhas: LinhaPrevia[] = useMemo(() => {
91	    if (!linhasCsv || !mapeamento) return [];
92	    const interpretadas = interpretarLinhas(linhasCsv, mapeamento);
93	    const duplicadas = marcarDuplicatas(interpretadas, estado, contaEfetiva);
94	    return interpretadas.map((l) => {
95	      const duplicata = duplicadas.has(l.indice);
96	      return {
97	        ...l,
98	        duplicata,
99	        selecionada: l.erro ? false : (selecao[l.indice] ?? !duplicata),
100	        categoriaId: l.erro ? undefined : (categoriasEscolhidas[l.indice] ?? sugerirCategoria(estado, l.descricao, l.tipo)),
101	        tags: l.erro ? [] : sugerirTags(estado, l.descricao, l.tipo),
102	      };
103	    });
104	  }, [linhasCsv, mapeamento, estado, contaEfetiva, selecao, categoriasEscolhidas]);
105	
106	  const aImportar = linhas.filter((l) => l.selecionada);
107	  const comErro = linhas.filter((l) => l.erro).length;
108	  const ignoradas = linhas.length - aImportar.length - comErro;
109	
110	  const confirmar = () => {
111	    if (!mapeamento) return;
112	    const itens = aImportar.map((l) => ({ data: l.data!, descricao: l.descricao, valor: l.valor, tipo: l.tipo, categoriaId: l.categoriaId ?? '', tags: l.tags }));
113	    let criada = '';
114	    const r = store.aplicar((s) => {
115	      const imp = importarTransacoes(s, contaEfetiva, itens, mapeamento, hojeISO());
116	      if (!imp.ok) return imp;
117	      criada = imp.valor.importacao.id;
118	      return { ok: true, valor: imp.valor.estado };
119	    });
120	    if (!r.ok) {
121	      setErro(r.erro);
122	      return;
123	    }
124	    setErro(null);
125	    setResumo({ importacaoId: criada, importadas: itens.length, ignoradas, comErro });
126	    reiniciar();
127	  };
128	
129	  const desfazer = (id: string) => {
130	    const r = store.aplicar((s) => desfazerImportacao(s, id));
131	    if (!r.ok) return setErro(r.erro);
132	    setErro(null);
133	    setResumo(null);
134	  };
135	
136	  const soltar = (e: DragEvent) => {
137	    e.preventDefault();
138	    setArrastando(false);
139	    void carregarArquivo(e.dataTransfer.files[0]);
140	  };
141	
142	  return (
143	    <div>
144	      <TituloPagina>Importar CSV</TituloPagina>
145	      <div className="space-y-4">
146	        {erro ? <Alerta>{erro}</Alerta> : null}
147	
148	        {resumo ? (
149	          <Alerta tipo="sucesso">
150	            <span className="flex flex-wrap items-center justify-between gap-2">
151	              <span data-testid="resumo">
152	                Importação concluída: {resumo.importadas} importadas, {resumo.ignoradas} ignoradas, {resumo.comErro} com erro.
153	              </span>
154	              <Botao variante="secundario" onClick={() => desfazer(resumo.importacaoId)}>
155	                Desfazer importação
156	              </Botao>
157	            </span>
158	          </Alerta>
159	        ) : null}
160	
161	        {contasAtivas.length === 0 ? (
162	          <EstadoVazio titulo="Nenhuma conta para receber a importação" acao={<Link to="/contas" className="font-medium text-emerald-800 underline">Criar uma conta</Link>}>
163	            As transações importadas precisam de uma conta de destino.
164	          </EstadoVazio>
165	        ) : (
166	          <Cartao titulo="1. Escolha o arquivo e a conta">
167	            <div className="grid gap-3 sm:grid-cols-2">
168	              <CampoSelect label="Conta de destino" value={contaEfetiva} onChange={(e) => setContaId(e.target.value)}>
169	                {contasAtivas.map((c) => (
170	                  <option key={c.id} value={c.id}>
171	                    {c.nome}
172	                  </option>
173	                ))}
174	              </CampoSelect>
175	              <div
176	                onDragOver={(e) => {
177	                  e.preventDefault();
178	                  setArrastando(true);
179	                }}
180	                onDragLeave={() => setArrastando(false)}
181	                onDrop={soltar}
182	                className={`flex flex-col items-center justify-center gap-2 rounded-md border-2 border-dashed p-4 text-center text-sm ${arrastando ? 'border-emerald-600 bg-emerald-50' : 'border-slate-300'}`}
183	              >
184	                <p className="text-slate-700">Arraste um arquivo .csv aqui ou</p>
185	                <Botao variante="secundario" onClick={() => entrada.current?.click()}>
186	                  Selecionar arquivo
187	                </Botao>
188	                <input
189	                  ref={entrada}
190	                  type="file"
191	                  accept=".csv,text/csv"
192	                  aria-label="Arquivo CSV"
193	                  className="sr-only"
194	                  onChange={(e) => {
195	                    void carregarArquivo(e.target.files?.[0]);
196	                    e.target.value = '';
197	                  }}
198	                />
199	                {nomeArquivo ? <p className="text-xs text-slate-600">Arquivo: {nomeArquivo}</p> : null}
200	              </div>
201	            </div>
202	          </Cartao>
203	        )}
204	
205	        {linhasCsv && mapeamento ? (
206	          <>
207	            <Cartao titulo="2. Mapeie as colunas">
208	              <CsvMapeamento colunas={linhasCsv[0].map((c, i) => (mapeamento.temCabecalho ? c : `${i + 1}`))} mapeamento={mapeamento} onChange={setMapeamento} />
209	            </Cartao>
210	            <Cartao
211	              titulo="3. Revise e confirme"
212	              acoes={
213	                <span className="text-sm text-slate-700" aria-live="polite" data-testid="contadores">
214	                  {aImportar.length} a importar · {ignoradas} ignoradas · {comErro} com erro
215	                </span>
216	              }
217	            >
218	              {linhas.length === 0 ? (
219	                <p className="text-sm text-slate-600">Nenhuma linha de dados no arquivo.</p>
220	              ) : (
221	                <CsvPrevia
222	                  linhas={linhas}
223	                  categorias={estado.categorias}
224	                  onSelecionar={(i, v) => setSelecao((s) => ({ ...s, [i]: v }))}
225	                  onCategoria={(i, c) => setCategoriasEscolhidas((s) => ({ ...s, [i]: c }))}
226	                />
227	              )}
228	              <div className="mt-4 flex flex-wrap gap-2">
229	                <Botao disabled={aImportar.length === 0} onClick={confirmar}>
230	                  {aImportar.length === 1 ? 'Importar 1 transação' : `Importar ${aImportar.length} transações`}
231	                </Botao>
232	                <Botao variante="secundario" onClick={reiniciar}>
233	                  Cancelar
234	                </Botao>
235	              </div>
236	            </Cartao>
237	          </>
238	        ) : null}
239	
240	        {!resumo && !linhasCsv && ultimaImportacao ? (
241	          <Cartao titulo="Última importação">
242	            <div className="flex flex-wrap items-center justify-between gap-2 text-sm text-slate-800">
243	              <span>
244	                {ultimaImportacao.transacaoIds.length} transações em {ultimaImportacao.data.split('-').reverse().join('/')}.
245	              </span>
246	              <Botao variante="secundario" onClick={() => desfazer(ultimaImportacao.id)}>
247	                Desfazer importação
248	              </Botao>
249	            </div>
250	          </Cartao>
251	        ) : null}
252	      </div>
253	    </div>
254	  );
255	}
