1	import { ID_OUTROS_DESPESA, ID_OUTROS_RECEITA } from '../data/categoriasPadrao';
2	import { efeitoTransacao } from './contas';
3	import { dataValida } from './date';
4	import { novoId, proximoTempo } from './id';
5	import { primeiraRegra } from './regras';
6	import { parseValor } from './money';
7	import { comTags, DESCRICAO_MAX, normalizarTexto, validarTransacao } from './transacoes';
8	import {
9	  falha,
10	  ok,
11	  type AppState,
12	  type Centavos,
13	  type DataISO,
14	  type FormatoData,
15	  type Importacao,
16	  type MapeamentoCsv,
17	  type Resultado,
18	  type TipoMovimento,
19	  type Transacao,
20	} from './types';
21	
22	export const TAMANHO_MAXIMO_BYTES = 5 * 1024 * 1024;
23	export const FORMATOS_DATA: FormatoData[] = ['dd/mm/aaaa', 'aaaa-mm-dd', 'dd-mm-aaaa'];
24	
25	export function validarArquivo(nome: string, tamanho: number): Resultado<void> {
26	  if (!/\.csv$/i.test(nome)) return falha('Selecione um arquivo com extensão .csv.');
27	  if (tamanho > TAMANHO_MAXIMO_BYTES) return falha('O arquivo passa de 5 MB e não pode ser importado.');
28	  return ok(undefined);
29	}
30	
31	/** Lê os bytes como UTF-8 e, se não forem válidos, como Windows-1252 (comum em bancos brasileiros). */
32	export function decodificar(bytes: Uint8Array): string {
33	  let texto: string;
34	  try {
35	    texto = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
36	  } catch {
37	    texto = new TextDecoder('windows-1252').decode(bytes);
38	  }
39	  return texto.replace(/^﻿/, '');
40	}
41	
42	export type Separador = ',' | ';';
43	
44	/** Escolhe entre `,` e `;` pela primeira linha, ignorando o que estiver entre aspas. */
45	export function detectarSeparador(texto: string): Separador {
46	  let virgulas = 0;
47	  let pontoEVirgulas = 0;
48	  let dentro = false;
49	  for (const c of texto) {
50	    if (c === '"') dentro = !dentro;
51	    else if (!dentro && (c === '\n' || c === '\r')) break;
52	    else if (!dentro && c === ',') virgulas++;
53	    else if (!dentro && c === ';') pontoEVirgulas++;
54	  }
55	  return pontoEVirgulas > 0 && pontoEVirgulas >= virgulas ? ';' : ',';
56	}
57	
58	/** Parser de CSV com campos entre aspas, aspas escapadas ("") e quebras de linha dentro de campo. */
59	export function parseCsv(texto: string, separador: Separador = detectarSeparador(texto)): string[][] {
60	  const linhas: string[][] = [];
61	  let linha: string[] = [];
62	  let campo = '';
63	  let dentro = false;
64	  let temConteudo = false;
65	
66	  const fecharCampo = () => {
67	    linha.push(campo);
68	    campo = '';
69	  };
70	  const fecharLinha = () => {
71	    fecharCampo();
72	    if (temConteudo || linha.some((c) => c.trim() !== '')) linhas.push(linha);
73	    linha = [];
74	    temConteudo = false;
75	  };
76	
77	  for (let i = 0; i < texto.length; i++) {
78	    const c = texto[i];
79	    if (dentro) {
80	      if (c === '"') {
81	        if (texto[i + 1] === '"') {
82	          campo += '"';
83	          i++;
84	        } else dentro = false;
85	      } else campo += c;
86	    } else if (c === '"') {
87	      dentro = true;
88	      temConteudo = true;
89	    } else if (c === separador) {
90	      fecharCampo();
91	    } else if (c === '\n' || c === '\r') {
92	      if (c === '\r' && texto[i + 1] === '\n') i++;
93	      fecharLinha();
94	    } else campo += c;
95	  }
96	  if (campo !== '' || linha.length > 0 || temConteudo) fecharLinha();
97	  return linhas;
98	}
99	
100	const padroesData: Record<FormatoData, RegExp> = {
101	  'dd/mm/aaaa': /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/,
102	  'aaaa-mm-dd': /^(\d{4})-(\d{1,2})-(\d{1,2})$/,
103	  'dd-mm-aaaa': /^(\d{1,2})-(\d{1,2})-(\d{4})$/,
104	};
105	
106	/** Converte no formato escolhido; devolve null se o texto não bater com ele ou a data não existir. */
107	export function parseData(texto: string, formato: FormatoData): DataISO | null {
108	  const m = padroesData[formato].exec(texto.trim());
109	  if (!m) return null;
110	  const [ano, mes, dia] = formato === 'aaaa-mm-dd' ? [m[1], m[2], m[3]] : [m[3], m[2], m[1]];
111	  const iso = `${ano}-${mes.padStart(2, '0')}-${dia.padStart(2, '0')}`;
112	  return dataValida(iso) ? iso : null;
113	}
114	
115	/** Primeiro formato em que todas as amostras não vazias são datas válidas. */
116	export function detectarFormatoData(amostras: string[]): FormatoData | null {
117	  const textos = amostras.map((a) => a.trim()).filter(Boolean);
118	  if (textos.length === 0) return null;
119	  return FORMATOS_DATA.find((f) => textos.every((t) => parseData(t, f) !== null)) ?? null;
120	}
121	
122	/** Valor com sinal; parênteses indicam negativo (`(50,00)`). */
123	export function parseValorCsv(texto: string): Centavos | null {
124	  const limpo = texto.trim();
125	  const parenteses = /^\(.*\)$/.test(limpo);
126	  const valor = parseValor(parenteses ? limpo.slice(1, -1) : limpo);
127	  if (valor === null) return null;
128	  return parenteses ? -Math.abs(valor) : valor;
129	}
130	
131	const cabecalhoContem = (cab: string, ...termos: string[]) => termos.some((t) => normalizarTexto(cab).includes(t));
132	
133	/** Sugere o mapeamento a partir do cabeçalho e dos dados; o usuário pode ajustar. */
134	export function adivinharMapeamento(linhas: string[][]): MapeamentoCsv {
135	  const primeira = linhas[0] ?? [];
136	  const colunas = Math.max(...linhas.map((l) => l.length), 0);
137	  const achar = (...termos: string[]) => {
138	    const i = primeira.findIndex((c) => cabecalhoContem(c, ...termos));
139	    return i >= 0 ? i : null;
140	  };
141	  const colData = achar('data');
142	  const temCabecalho = colData !== null || achar('descri', 'historico', 'valor') !== null;
143	  const dados = temCabecalho ? linhas.slice(1) : linhas;
144	  const credito = achar('credito', 'entrada');
145	  const debito = achar('debito', 'saida');
146	  const valor = achar('valor', 'quantia');
147	  const usaDuasColunas = valor === null && credito !== null && debito !== null;
148	  const data = colData ?? 0;
149	  const descricao = achar('descri', 'historico', 'lancamento', 'estabelecimento') ?? Math.min(1, Math.max(colunas - 1, 0));
150	  const formatoData = detectarFormatoData(dados.map((l) => l[data] ?? '')) ?? 'dd/mm/aaaa';
151	  return {
152	    colData: data,
153	    colDescricao: descricao,
154	    colValor: usaDuasColunas ? null : (valor ?? Math.min(2, Math.max(colunas - 1, 0))),
155	    colCredito: usaDuasColunas ? credito : null,
156	    colDebito: usaDuasColunas ? debito : null,
157	    formatoData,
158	    temCabecalho,
159	  };
160	}
161	
162	export interface LinhaInterpretada {
163	  /** Posição da linha no arquivo (começando em 1), para exibir ao usuário. */
164	  indice: number;
165	  data: DataISO | null;
166	  descricao: string;
167	  valor: Centavos;
168	  tipo: TipoMovimento;
169	  erro?: string;
170	}
171	
172	export function interpretarLinhas(linhas: string[][], m: MapeamentoCsv): LinhaInterpretada[] {
173	  const resultado: LinhaInterpretada[] = [];
174	  linhas.forEach((celulas, posicao) => {
175	    if (m.temCabecalho && posicao === 0) return;
176	    const celula = (i: number | null) => (i === null ? '' : (celulas[i] ?? '').trim());
177	    const dataTexto = celula(m.colData);
178	    const data = dataTexto ? parseData(dataTexto, m.formatoData) : null;
179	    const descricao = celula(m.colDescricao).replace(/\s+/g, ' ').slice(0, DESCRICAO_MAX);
180	    const linha: LinhaInterpretada = { indice: posicao + 1, data, descricao, valor: 0, tipo: 'despesa' };
181	
182	    let erroValor: string | undefined;
183	    if (m.colValor !== null) {
184	      const texto = celula(m.colValor);
185	      const v = texto === '' ? null : parseValorCsv(texto);
186	      if (texto === '') erroValor = 'Valor ausente';
187	      else if (v === null) erroValor = 'Valor inválido';
188	      else if (v === 0) erroValor = 'Valor zero';
189	      else {
190	        linha.tipo = v < 0 ? 'despesa' : 'receita';
191	        linha.valor = Math.abs(v);
192	      }
193	    } else {
194	      const deb = celula(m.colDebito) === '' ? 0 : parseValorCsv(celula(m.colDebito));
195	      const cred = celula(m.colCredito) === '' ? 0 : parseValorCsv(celula(m.colCredito));
196	      if (deb === null || cred === null) erroValor = 'Valor inválido';
197	      else if (deb !== 0 && cred !== 0) erroValor = 'Crédito e débito preenchidos na mesma linha';
198	      else if (deb === 0 && cred === 0) erroValor = 'Valor ausente';
199	      else if (deb !== 0) {
200	        linha.tipo = 'despesa';
201	        linha.valor = Math.abs(deb);
202	      } else {
203	        linha.tipo = 'receita';
204	        linha.valor = Math.abs(cred as number);
205	      }
206	    }
207	
208	    if (!dataTexto) linha.erro = 'Data ausente';
209	    else if (!data) linha.erro = 'Data inválida para o formato escolhido';
210	    else if (erroValor) linha.erro = erroValor;
211	    resultado.push(linha);
212	  });
213	  return resultado;
214	}
215	
216	const chaveDuplicata = (data: string, efeito: Centavos, descricao: string) => `${data}|${efeito}|${normalizarTexto(descricao)}`;
217	
218	/** Mesma conta, mesma data, mesmo valor e mesma descrição normalizada. */
219	export function marcarDuplicatas(linhas: LinhaInterpretada[], estado: AppState, contaId: string): Set<number> {
220	  const existentes = new Set(estado.transacoes.filter((t) => t.contaId === contaId).map((t) => chaveDuplicata(t.data, efeitoTransacao(t), t.descricao)));
221	  const duplicadas = new Set<number>();
222	  for (const l of linhas) {
223	    if (l.erro || !l.data) continue;
224	    const efeito = l.tipo === 'receita' ? l.valor : -l.valor;
