235	/**
236	 * Sugere a categoria da primeira regra ativa que casar; senão reutiliza a categoria de uma transação anterior com a mesma descrição normalizada;
237	 * sem histórico, usa "Outros" do tipo correspondente.
238	 */
239	export function sugerirCategoria(estado: AppState, descricao: string, tipo: TipoMovimento): string | undefined {
240	  const regra = primeiraRegra(estado, descricao, tipo);
241	  if (regra) return regra.categoriaId;
242	  const ativas = new Map(estado.categorias.filter((c) => !c.arquivada && c.tipo === tipo).map((c) => [c.id, c]));
243	  const alvo = normalizarTexto(descricao);
244	  if (alvo) {
245	    let melhor: Transacao | undefined;
246	    for (const t of estado.transacoes) {
247	      if (t.tipo === tipo && ativas.has(t.categoriaId) && normalizarTexto(t.descricao) === alvo && (!melhor || t.criadaEm > melhor.criadaEm)) melhor = t;
248	    }
249	    if (melhor) return melhor.categoriaId;
250	  }
251	  const idOutros = tipo === 'despesa' ? ID_OUTROS_DESPESA : ID_OUTROS_RECEITA;
252	  if (ativas.has(idOutros)) return idOutros;
253	  const porNome = [...ativas.values()].find((c) => normalizarTexto(c.nome) === 'outros');
254	  return (porNome ?? [...ativas.values()][0])?.id;
255	}
