266	/** Grava todos os itens de uma vez ou nenhum: qualquer item inválido cancela a importação inteira. */
267	export function importarTransacoes(
268	  estado: AppState,
269	  contaId: string,
270	  itens: ItemImportacao[],
271	  mapeamento: MapeamentoCsv,
272	  hoje: DataISO,
273	): Resultado<{ estado: AppState; importacao: Importacao }> {
274	  if (itens.length === 0) return falha('Nenhuma linha selecionada para importar.');
275	  const importacaoId = novoId();
276	  const novas: Transacao[] = [];
277	  for (const item of itens) {
278	    const v = validarTransacao(estado, { contaId, ...item });
279	    if (!v.ok) return falha(`Linha de ${item.data} ("${item.descricao}"): ${v.erro}`);
280	    novas.push(comTags({ ...v.valor, id: novoId(), criadaEm: proximoTempo(), importacaoId }));
281	  }
282	  const importacao: Importacao = { id: importacaoId, data: hoje, contaId, transacaoIds: novas.map((t) => t.id) };
283	  return ok({
284	    importacao,
285	    estado: {
286	      ...estado,
287	      transacoes: [...estado.transacoes, ...novas],
288	      importacoes: [...estado.importacoes, importacao],
289	      mapeamentosCsv: { ...estado.mapeamentosCsv, [contaId]: mapeamento },
290	    },
291	  });
292	}
293	
294	/** Remove exatamente as transações criadas pela importação. */
295	export function desfazerImportacao(estado: AppState, importacaoId: string): Resultado<AppState> {
296	  const importacao = estado.importacoes.find((i) => i.id === importacaoId);
297	  if (!importacao) return falha('Importação não encontrada.');
298	  const ids = new Set(importacao.transacaoIds);
299	  return ok({
300	    ...estado,
301	    transacoes: estado.transacoes.filter((t) => !ids.has(t.id)),
302	    importacoes: estado.importacoes.filter((i) => i.id !== importacaoId),
303	  });
304	}
